// Generates the TypeScript and Python type declarations of the bindings
// from the JSON Schema of the Rust model (`abap schema`).
//
// usage: node tools/gen-types.mjs [--check]
//   --check  fail if the generated files are not up to date (for CI)

import {execFileSync} from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import {fileURLToPath} from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const tsFile = path.join(root, "bindings", "node", "types.d.ts");
const pyFile = path.join(root, "bindings", "python", "python", "abap_parser", "types.py");
const HEADER = "generated by tools/gen-types.mjs from the JSON Schema of the Rust model, do not edit";

const schema = JSON.parse(execFileSync("cargo", ["run", "-q", "-p", "abap-cli", "--", "schema"],
  {cwd: root, maxBuffer: 1 << 26}).toString());

// all named definitions, the two roots included
const defs = {...schema.symbols.$defs, ...schema.statements.$defs, ...schema.db_access.$defs,
  ...schema.calls.$defs, ...schema.call_graph.$defs, ...schema.logic.$defs, ...schema.cds.$defs};
const {$defs: _g, $schema: _h, ...cds} = schema.cds;
defs.CdsDefinition = cds;
const {$defs: _e, $schema: _f, ...fileLogic} = schema.logic;
defs.FileLogic = fileLogic;
const {$defs: _c, $schema: _d, ...callGraph} = schema.call_graph;
defs.CallGraph = callGraph;
const {$defs: _a, $schema: _b, ...fileSymbols} = schema.symbols;
defs.FileSymbols = fileSymbols;
const names = Object.keys(defs).sort();

const refName = (ref) => ref.replace("#/$defs/", "");

/** variants of a string enum, or undefined */
function literals(s) {
  if (s.enum) {
    return s.enum;
  }
  // variants with doc comments come as {const}, the others grouped as {enum}
  if (s.oneOf && s.oneOf.every((v) => v.const !== undefined || v.enum !== undefined)) {
    return s.oneOf.flatMap((v) => v.enum ?? [v.const]);
  }
  return undefined;
}

/** strips "null" from a property type, absent values are omitted in the JSON */
function nonNull(s) {
  if (Array.isArray(s.type)) {
    const types = s.type.filter((t) => t !== "null");
    return {...s, type: types.length === 1 ? types[0] : types};
  }
  if (s.anyOf) {
    const rest = s.anyOf.filter((v) => v.type !== "null");
    return rest.length === 1 ? {...rest[0], description: s.description} : {...s, anyOf: rest};
  }
  return s;
}

function tsType(s) {
  s = nonNull(s);
  if (s.$ref) {
    return refName(s.$ref);
  }
  const lits = literals(s);
  if (lits) {
    return lits.map((l) => JSON.stringify(l)).join(" | ");
  }
  switch (s.type) {
    case "string": return "string";
    case "integer":
    case "number": return "number";
    case "boolean": return "boolean";
    case "array": return `${tsType(s.items)}[]`;
    default: throw new Error("unsupported schema: " + JSON.stringify(s));
  }
}

function pyType(s) {
  s = nonNull(s);
  if (s.$ref) {
    return refName(s.$ref);
  }
  const lits = literals(s);
  if (lits) {
    return `Literal[${lits.map((l) => JSON.stringify(l)).join(", ")}]`;
  }
  switch (s.type) {
    case "string": return "str";
    case "integer": return "int";
    case "number": return "float";
    case "boolean": return "bool";
    case "array": return `List[${pyType(s.items)}]`;
    default: throw new Error("unsupported schema: " + JSON.stringify(s));
  }
}

function tsDoc(text, indent) {
  return text ? `${indent}/** ${text.replace(/\n+/g, " ")} */\n` : "";
}

function generateTs() {
  let out = `// ${HEADER}\n`;
  for (const name of names) {
    const s = defs[name];
    out += "\n" + tsDoc(s.description, "");
    if (s.type !== "object") {
      out += `export type ${name} = ${tsType(s)};\n`;
      continue;
    }
    out += `export interface ${name} {\n`;
    const required = new Set(s.required ?? []);
    for (const [prop, ps] of Object.entries(s.properties)) {
      out += tsDoc(ps.description, "  ");
      out += `  ${prop}${required.has(prop) ? "" : "?"}: ${tsType(ps)};\n`;
    }
    out += "}\n";
  }
  return out;
}

const PY_KEYWORDS = new Set(["class", "def", "from", "import", "in", "is", "not", "or", "and", "if", "else",
  "for", "while", "return", "global", "lambda", "pass", "raise", "try", "with", "yield", "None", "True", "False"]);

function pyDoc(text, indent) {
  return text ? `${indent}"""${text.replace(/\n+/g, " ").replace(/"/g, "'")}"""\n` : "";
}

function generatePy() {
  let out = `"""Types of the dictionaries returned by abap_parser.\n\n${HEADER}.\n"""\n\n`;
  out += "from __future__ import annotations\n\nfrom typing import List, Literal, TypedDict\n";
  // aliases first, TypedDicts refer to them by name
  for (const name of names.filter((n) => defs[n].type !== "object")) {
    out += `\n${name} = ${pyType(defs[name])}\n`;
    out += pyDoc(defs[name].description, "");
  }
  for (const name of names.filter((n) => defs[n].type === "object")) {
    const s = defs[name];
    const required = new Set(s.required ?? []);
    const props = Object.entries(s.properties);
    const req = props.filter(([p]) => required.has(p));
    const opt = props.filter(([p]) => !required.has(p));
    if (props.some(([p]) => PY_KEYWORDS.has(p))) {
      // keys like "class" need the functional syntax
      // quoted: functional TypedDicts evaluate their types at runtime, forward references must be strings
      const dict = (list) => "{" + list.map(([p, ps]) => `${JSON.stringify(p)}: ${JSON.stringify(pyType(ps))}`).join(", ") + "}";
      if (opt.length) {
        out += `\n\n_${name}Required = TypedDict("_${name}Required", ${dict(req)})\n`;
        out += `\n\n_${name}Optional = TypedDict("_${name}Optional", ${dict(opt)}, total=False)\n`;
        out += `\n\nclass ${name}(_${name}Required, _${name}Optional):\n`;
        out += pyDoc(s.description, "    ") || "    pass\n";
      } else {
        out += `\n\n${name} = TypedDict("${name}", ${dict(req)})\n`;
        out += pyDoc(s.description, "");
      }
      continue;
    }
    const field = ([p, ps]) => `    ${p}: ${pyType(ps)}\n` + pyDoc(ps.description, "    ");
    // optional keys go into a total=False subclass, works on Python 3.9
    out += `\n\nclass ${opt.length ? "_" + name + "Required" : name}(TypedDict):\n`;
    out += pyDoc(opt.length ? "" : s.description, "    ");
    out += req.length ? req.map(field).join("") : "    pass\n";
    if (opt.length) {
      out += `\n\nclass ${name}(_${name}Required, total=False):\n`;
      out += pyDoc(s.description, "    ");
      out += opt.map(field).join("");
    }
  }
  return out;
}

const outputs = [[tsFile, generateTs()], [pyFile, generatePy()]];
if (process.argv.includes("--check")) {
  // a checkout on Windows may have CRLF line ends
  const read = (f) => fs.readFileSync(f, "utf8").replace(/\r\n/g, "\n");
  const stale = outputs.filter(([f, text]) => !fs.existsSync(f) || read(f) !== text);
  if (stale.length > 0) {
    console.error("out of date, run node tools/gen-types.mjs: " + stale.map(([f]) => path.relative(root, f)).join(", "));
    process.exit(1);
  }
} else {
  for (const [f, text] of outputs) {
    fs.writeFileSync(f, text);
    console.log("wrote " + path.relative(root, f));
  }
}
